def shift_right_and_fill(lst, n, fill):
    size = len(lst)
    if n <= 0:
        return lst[:]
    if n >= size:
        return [fill] * size
    kept = lst[:size - n]
    return [fill] * n + kept

def interleave_strings(s1, s2):
    result = []
    length = max(len(s1), len(s2))
    for idx in range(length):
        if idx < len(s1):
            result.append(s1[idx])
        if idx < len(s2):
            result.append(s2[idx])
    return ''.join(result)

def atbash_cipher(s):
    result = []
    for c in s:
        if 'a' <= c <= 'z':
            result.append(chr(ord('z') - (ord(c) - ord('a'))))
        elif 'A' <= c <= 'Z':
            result.append(chr(ord('Z') - (ord(c) - ord('A'))))
        else:
            result.append(c)
    return ''.join(result)

