def is_valid_spaced_credit_card(s):
    parts = s.split(' ')
    if len(parts) != 4:
        return False
    for p in parts:
        if len(p) != 4 or not p.isdigit():
            return False
    digits = ''.join(parts)
    total = 0
    position = 0
    for ch in reversed(digits):
        value = int(ch)
        if position % 2 == 1:
            value *= 2
            if value > 9:
                value -= 9
        total += value
        position += 1
    return total % 10 == 0

