def sliding_window_average(lst, k):
    if not isinstance(k, int) or k <= 0 or k > len(lst):
        return []
    out = []
    for i in range(len(lst) - k + 1):
        window = lst[i:i + k]
        out.append(round(sum(window) / k, 4))
    return out

